  $forbidden=array_map('sanitize_key',array_merge((array)($contract['forbidden_widgets']??array()),(array)($requirements['forbidden_widgets']??array())));if(in_array($name,$forbidden,true))$reject[]='forbidden_widget:'.$name;$forbidden_intents=array_map('sanitize_key',array_merge((array)($contract['forbidden_intents']??array()),(array)($requirements['forbidden_intents']??array())));if($primary&&in_array($primary,$forbidden_intents,true))$reject[]='primary_intent_conflict:'.$primary;
