  $score=0;$breakdown=array();$preferred=array_map('sanitize_key',array_merge((array)($contract['preferred_widgets']??array()),(array)($requirements['preferred_widgets']??array())));if(in_array($name,$preferred,true)){$score+=.30;$breakdown['preferred_widget']=.30;}$wanted=array_map('sanitize_key',(array)($contract['intents']??array()));if($primary&&in_array($primary,$wanted,true)){$score+=.20;$breakdown['primary_intent']=.20;}elseif(array_intersect($intents,$wanted)){$score+=.12;$breakdown['secondary_intent']=.12;}$tokens=(array)($semantic['tokens']??array());$overlap=Design_Core_Elementor_Semantic_Tokenizer::overlap($tokens,array_merge((array)($requirements['keywords']??array()),$wanted));$identity=min(.20,.20*$overlap);$score+=$identity;if($identity)$breakdown['identity']=round($identity,4);$need=max(1,count($required_caps)+count($groups)+count((array)($requirements['required_controls']??array())));$runtime=min(.20,.20*count(array_unique($evidence))/$need);$score+=$runtime;if($runtime)$breakdown['runtime_contract']=round($runtime,4);if((!empty($requirements['repeated'])||in_array('repeater',$required_caps,true))&&in_array('repeater',$supports,true)){$score+=.08;$breakdown['repeater_editability']=.08;}if(in_array('responsive',$supports,true)){$score+=.04;$breakdown['responsive_editability']=.04;}if(in_array($name,array('text-editor','button','heading','html'),true)&&!empty($requirements['composite_component'])){$score-=.25;$breakdown['generic_widget_penalty']=-.25;}if($unverified){$pen=min(.18,.06*count($unverified));$score-=$pen;$breakdown['behavior_gap_penalty']=-$pen;}$score=max(0,min(1,round($score,4)));return array('status'=>'compatible','score'=>$score,'name'=>$name,'rejections'=>array(),'evidence'=>array_values(array_unique($evidence)),'breakdown'=>$breakdown,'unverified_behaviors'=>$unverified,'schema_fingerprint'=>(string)($widget['schema_fingerprint']??$schema['fingerprint']??''),'control_count'=>count($controls));
 }
 private static function behaviors($name){$map=array('mega-menu'=>array('navigate','menu-toggle'),'nav-menu'=>array('navigate','menu-toggle'),'accordion'=>array('disclosure'),'nested-accordion'=>array('disclosure'),'toggle'=>array('disclosure'),'form'=>array('data-entry','submit'),'button'=>array('activate','navigate'),'icon-list'=>array('navigate'),'dc-global-time-bar'=>array('live-time'),'dc-steps'=>array('ordered-sequence'),'dc-responsive-table'=>array('compare-data','tabular-data'),'dc-jump-nav'=>array('navigate','same-page-anchor','active-section','keyboard-horizontal-scroll'),'dc-enquiry-drawer'=>array('data-entry','open-drawer','prefill','focus-trap','escape-close'),'tabs'=>array('tabbed-content'),'nested-tabs'=>array('tabbed-content'),'image-carousel'=>array('carousel-navigation'),'media-carousel'=>array('carousel-navigation'),'social-icons'=>array('navigate-social'),'counter'=>array('animated-number'),'price-table'=>array('commerce-offer'),'loop-grid'=>array('query-content'),'posts'=>array('query-content'),'search'=>array('search-submit'),'video'=>array('play-media'));return $map[$name]??array();}
